-- Banque Téranga (fictive) · cœur bancaire · MySQL 8
-- Crée la base teranga_core et le compte de service teranga_app (lecture et modification
-- contrôlées par SQLVault Gateway). Rejouable : la base est recréée.
DROP DATABASE IF EXISTS teranga_core;
CREATE DATABASE teranga_core CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
DROP USER IF EXISTS 'teranga_app'@'%';
CREATE USER 'teranga_app'@'%' IDENTIFIED BY 'Teranga#Core2026';
GRANT SELECT, INSERT, UPDATE, DELETE ON teranga_core.* TO 'teranga_app'@'%';
USE teranga_core;

CREATE TABLE agences (
  id INT PRIMARY KEY,
  code CHAR(3) NOT NULL UNIQUE,
  nom VARCHAR(80) NOT NULL,
  ville VARCHAR(60) NOT NULL,
  region VARCHAR(60) NOT NULL
) COMMENT 'Réseau d''agences';

CREATE TABLE clients (
  id INT PRIMARY KEY,
  numero_client VARCHAR(12) NOT NULL UNIQUE,
  civilite VARCHAR(10) NOT NULL,
  nom VARCHAR(80) NOT NULL,
  prenom VARCHAR(60) NOT NULL,
  date_naissance DATE NULL,
  telephone VARCHAR(20) NOT NULL,
  email VARCHAR(120) NOT NULL,
  ville VARCHAR(60) NOT NULL,
  agence_id INT NOT NULL,
  segment VARCHAR(20) NOT NULL,
  conseiller VARCHAR(60) NOT NULL,
  date_entree DATE NOT NULL,
  actif BOOLEAN NOT NULL,
  CONSTRAINT fk_clients_agence FOREIGN KEY (agence_id) REFERENCES agences (id)
) COMMENT 'Clients particuliers, professionnels et entreprises';
CREATE INDEX ix_clients_segment ON clients (segment);

CREATE TABLE comptes (
  id INT PRIMARY KEY,
  numero_compte VARCHAR(12) NOT NULL UNIQUE,
  iban VARCHAR(34) NOT NULL UNIQUE,
  client_id INT NOT NULL,
  type_compte VARCHAR(20) NOT NULL,
  devise CHAR(3) NOT NULL,
  solde DECIMAL(16,2) NOT NULL,
  date_ouverture DATE NOT NULL,
  statut VARCHAR(10) NOT NULL,
  CONSTRAINT fk_comptes_client FOREIGN KEY (client_id) REFERENCES clients (id)
);

CREATE TABLE operations (
  id INT PRIMARY KEY,
  compte_id INT NOT NULL,
  date_operation DATETIME NOT NULL,
  type_operation VARCHAR(40) NOT NULL,
  libelle VARCHAR(120) NOT NULL,
  montant DECIMAL(16,2) NOT NULL,
  canal VARCHAR(10) NOT NULL,
  CONSTRAINT fk_operations_compte FOREIGN KEY (compte_id) REFERENCES comptes (id)
);
CREATE INDEX ix_operations_date ON operations (date_operation);

